import * as T from './vendor/three.module.js';
// One nearest, front-facing mirror updates at 6 Hz. The other mirrors retain
// their last reflection. No recursive passes or shadow-map refreshes.
export function createBoutiqueMirrors(panels){
 const entries=panels.map(panel=>{const target=new T.WebGLRenderTarget(192,384,{depthBuffer:true});const matrix=new T.Matrix4();const material=new T.ShaderMaterial({uniforms:{image:{value:target.texture},textureMatrix:{value:matrix}},vertexShader:'uniform mat4 textureMatrix; varying vec4 mirrorUv; void main(){vec4 world=modelMatrix*vec4(position,1.0);mirrorUv=textureMatrix*world;gl_Position=projectionMatrix*viewMatrix*world;}',fragmentShader:'uniform sampler2D image; varying vec4 mirrorUv; void main(){vec3 colour=texture2DProj(image,mirrorUv).rgb;gl_FragColor=vec4(mix(colour,vec3(0.72,0.82,0.9),0.06),1.0); \n #include <tonemapping_fragment> \n #include <colorspace_fragment> }'});const initial=panel.material;return {panel,target,matrix,material,initial};});
 const virtual=new T.PerspectiveCamera(),position=new T.Vector3(),direction=new T.Vector3(),plane=new T.Plane(),clip=new T.Vector4(),q=new T.Vector4();let last=-Infinity;
 function render(renderer,scene,camera,now,subject=camera.position){if(now-last<1000/6||!renderer.getRenderTarget)return;scene.updateMatrixWorld(true);camera.updateMatrixWorld();let best=null,distance=Infinity;for(const e of entries){e.panel.getWorldPosition(position);const dz=camera.position.z-position.z,d=subject.distanceToSquared(position);if(dz>.15&&subject.z>position.z+.05&&d<distance){best=e;distance=d;}}if(!best)return;last=now;best.panel.getWorldPosition(position);
  virtual.copy(camera);virtual.position.copy(camera.position);virtual.position.z=2*position.z-camera.position.z;camera.getWorldDirection(direction);direction.z=-direction.z;virtual.up.copy(camera.up);virtual.up.z=-virtual.up.z;virtual.lookAt(virtual.position.clone().add(direction));virtual.updateMatrixWorld();virtual.matrixWorldInverse.copy(virtual.matrixWorld).invert();
  // Clip everything behind the mirror plane in the reflected camera.
  plane.setFromNormalAndCoplanarPoint(new T.Vector3(0,0,1),position).applyMatrix4(virtual.matrixWorldInverse);clip.set(plane.normal.x,plane.normal.y,plane.normal.z,plane.constant);const p=virtual.projectionMatrix.elements;q.set((Math.sign(clip.x)+p[8])/p[0],(Math.sign(clip.y)+p[9])/p[5],-1,(1+p[10])/p[14]);clip.multiplyScalar(2/clip.dot(q));p[2]=clip.x;p[6]=clip.y;p[10]=clip.z+1-.003;p[14]=clip.w;virtual.projectionMatrixInverse.copy(virtual.projectionMatrix).invert();
  best.matrix.set(.5,0,0,.5,0,.5,0,.5,0,0,.5,.5,0,0,0,1).multiply(virtual.projectionMatrix).multiply(virtual.matrixWorldInverse);
  const previous=renderer.getRenderTarget(),auto=renderer.shadowMap.autoUpdate,needs=renderer.shadowMap.needsUpdate,visible=panels.map(p=>p.visible),xr=renderer.xr?.enabled;
  try{panels.forEach(p=>p.visible=false);renderer.shadowMap.autoUpdate=false;renderer.shadowMap.needsUpdate=false;if(renderer.xr)renderer.xr.enabled=false;renderer.setRenderTarget(best.target);renderer.clear();renderer.render(scene,virtual);best.panel.material=best.material;}finally{renderer.setRenderTarget(previous);renderer.shadowMap.autoUpdate=auto;renderer.shadowMap.needsUpdate=needs;if(renderer.xr)renderer.xr.enabled=xr;panels.forEach((p,i)=>p.visible=visible[i]);}
 }
 return {render,dispose(){for(const e of entries){e.target.dispose();e.material.dispose();e.initial.dispose();}}};
}
